<script lang="ts">
import type { ApexConfig, ApexLocale, ApexSavedInquiry } from '../../../../core/src/apex/mod.ts';
import { accountDate, accountStatus } from './presentation.ts';
import { useResolver } from '../url.ts';
let { config, locale, record, demo = false, onClose, canRemove = false, onRemove }: { config: ApexConfig; locale: ApexLocale; record: ApexSavedInquiry | null; demo?: boolean; onClose: () => void; canRemove?: boolean; onRemove?: () => Promise<void> } = $props();
const resolve = useResolver();
let dialog = $state<HTMLDialogElement>();
let copied = $state(false);
let experience = $derived(config.experiences.find(item => item.id === record?.experienceId));
const ui = (es: string, en: string) => locale === 'es' ? es : en;
const stageIndex = (status: ApexSavedInquiry['status']) => ({ draft: 0, requested: 1, quoted: 2, confirmed: 3, completed: 4, cancelled: -1 })[status];
$effect(() => { if (record && dialog && !dialog.open) { copied = false; dialog.showModal(); } else if (!record && dialog?.open) dialog.close(); });
async function copyReference() { if (!record?.reference) return; try { await navigator.clipboard.writeText(record.reference); copied = true; } catch { copied = false; } }
</script>
<dialog bind:this={dialog} class="account-record-dialog" onclose={onClose} aria-labelledby="account-detail-title">
 {#if record}
  <div class="account-detail-cover"><img src={experience?.image ?? config.brand.background} alt={experience?.title[locale] ?? ''}/><div class="account-detail-cover-shade"></div><span class="account-status-chip" data-status={record.status}>{accountStatus(record.status, locale)}</span>{#if demo}<span class="account-detail-example">{ui('EJEMPLO · SIN RESERVA REAL', 'EXAMPLE · NO REAL BOOKING')}</span>{/if}<button class="account-dialog-close" type="button" onclick={() => dialog?.close()} aria-label={ui('Cerrar detalle', 'Close details')}>×</button></div>
  <div class="account-detail-content">
   <p class="account-kicker">{record.reference ?? ui('TU CONSULTA', 'YOUR INQUIRY')}</p><h2 id="account-detail-title">{experience?.title[locale] ?? record.experienceId}</h2><p class="account-detail-intro">{experience?.description[locale]}</p>
   {#if demo}<div class="account-demo-note"><span aria-hidden="true">◌</span><p>{ui('Estos datos son una muestra del área personal. No se ha creado, pagado ni confirmado una reserva real.', 'These are sample personal-area records. No real reservation has been created, paid for or confirmed.')}</p></div>{:else if ['draft','requested','quoted'].includes(record.status)}<div class="account-demo-note"><p>{ui('Una consulta o propuesta requiere confirmación expresa de APEX para convertirse en reserva.', 'An inquiry or proposal requires explicit APEX confirmation to become a reservation.')}</p></div>{/if}
   <dl class="account-detail-facts"><div><dt>{ui('Fecha de la experiencia', 'Experience date')}</dt><dd>{accountDate(record.date, locale)}</dd></div><div><dt>{ui('Tu grupo', 'Your group')}</dt><dd>{record.people} {ui('personas', 'people')}</dd></div><div><dt>{ui('Idioma solicitado', 'Requested language')}</dt><dd>{record.language === 'es' ? 'Español' : 'English'}</dd></div><div><dt>{ui('Estado', 'Status')}</dt><dd>{accountStatus(record.status, locale)}{demo ? ` · ${ui('Ejemplo', 'Example')}` : ''}</dd></div></dl>
   {#if record.quote}<div class="account-detail-quote"><div><p class="account-kicker">{ui('PROPUESTA', 'PROPOSAL')}{demo ? ` · ${ui('EJEMPLO', 'EXAMPLE')}` : ''}</p><p>{record.quote}</p></div><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-3-2-3 2-3-2-3 2V3Z"/><path d="M9 8h6M9 12h6"/></svg></div>{/if}
   <section class="account-detail-section"><h3>{ui('El recorrido de tu solicitud', 'Your inquiry journey')}</h3><ol class="account-progress">{#each [ui('Guardada', 'Saved'),ui('En revisión', 'In review'),ui('Propuesta', 'Proposal'),ui('Confirmada', 'Confirmed'),ui('Vivida', 'Completed')] as stage, i}<li class:complete={stageIndex(record.status)>=i} class:current={stageIndex(record.status)===i}><span>{stageIndex(record.status)>i?'✓':String(i+1).padStart(2,'0')}</span><p>{stage}</p></li>{/each}</ol>{#if record.status==='cancelled'}<p class="account-detail-note">{ui('Esta solicitud aparece como cancelada en el historial.', 'This request is marked cancelled in your history.')}</p>{/if}</section>
   <div class="account-detail-columns"><section class="account-detail-section"><h3>{experience?.kind==='flight'?ui('Propuesta de experiencia', 'Experience proposal'):ui('Tu programa', 'Your program')}</h3><ul class="account-included-list">{#each experience?.activities ?? [] as activity}<li><span aria-hidden="true">↗</span>{activity[locale]}</li>{/each}</ul><p class="account-detail-note">{experience?.kind==='flight'?ui('Ruta, aeronave y duración se acuerdan en la propuesta.', 'Route, aircraft and duration are agreed in the proposal.'):ui('El orden, la duración y los requisitos se acuerdan con APEX.', 'Order, duration and requirements are agreed with APEX.')}</p></section><section class="account-detail-section"><h3>{ui('Logística solicitada', 'Requested logistics')}</h3><dl class="account-logistics"><div><dt>{ui('Recogida', 'Pickup')}</dt><dd>{record.pickup || ui('Por acordar con APEX', 'To be agreed with APEX')}</dd></div><div><dt>{ui('Regreso', 'Return')}</dt><dd>{record.dropoff || record.pickup || ui('Por acordar con APEX', 'To be agreed with APEX')}</dd></div>{#if record.occasion}<div><dt>{ui('Ocasión', 'Occasion')}</dt><dd>{record.occasion==='birthday'?ui('Cumpleaños','Birthday'):record.occasion==='anniversary'?ui('Aniversario','Anniversary'):record.occasion==='other'?ui('Otra celebración','Other celebration'):record.occasion}</dd></div>{/if}{#if record.notes}<div><dt>{ui('Comentarios', 'Notes')}</dt><dd>{record.notes}</dd></div>{/if}</dl></section></div>
   {#if demo&&canRemove}<div class="account-remove-local"><p>{ui('Esta consulta de ejemplo se guardó en este navegador. Puedes retirarla sin afectar las muestras iniciales.','This example inquiry was saved in this browser. You can remove it without affecting the initial samples.')}</p><button type="button" onclick={()=>onRemove?.()}>{ui('Eliminar consulta de ejemplo','Remove example inquiry')}</button></div>{/if}<div class="account-detail-footer">{#if record.reference}<button class="account-subtle-button" type="button" onclick={copyReference}>{copied?'✓ ':''}{copied?ui('Referencia copiada', 'Reference copied'):ui('Copiar referencia', 'Copy reference')}</button>{/if}<a class="button" href={resolve(`/experiencias/${record.experienceId}/`)}>{ui('Explorar experiencia', 'Explore experience')} ↗</a><button class="button outline" type="button" onclick={() => dialog?.close()}>{ui('Volver a mi cuenta', 'Back to my account')}</button></div>
  </div>
 {/if}
</dialog>
